import { describe, expect, it } from 'vitest';

import { classifyPingResult } from './agent-ping.js';

describe('classifyPingResult', () => {
  it('treats a normal text reply as ok', () => {
    expect(classifyPingResult(0, 'pong\n')).toBe('ok');
  });

  it('detects Anthropic auth errors printed as a chat reply', () => {
    expect(
      classifyPingResult(
        0,
        'Failed to authenticate. API Error: 401 {"type":"error","error":{"type":"authentication_error","message":"Invalid bearer token"}}',
      ),
    ).toBe('auth_error');
  });

  it('detects auth errors on stderr too', () => {
    expect(classifyPingResult(1, '', 'Authentication error')).toBe('auth_error');
  });

  it('detects Claude Code login banners printed as a chat reply', () => {
    expect(
      classifyPingResult(0, 'Invalid API key · Please run /login'),
    ).toBe('auth_error');
    expect(
      classifyPingResult(0, 'Not logged in · Please run /login'),
    ).toBe('auth_error');
  });

  it('preserves socket errors', () => {
    expect(classifyPingResult(2, '')).toBe('socket_error');
  });

  it('treats empty output as no reply', () => {
    expect(classifyPingResult(0, '')).toBe('no_reply');
  });
});

/**
 * Step: auth — Verify or register an Anthropic credential in OneCLI.
 *
 * Modes:
 *   --check                   (default) Verify an Anthropic secret exists.
 *   --create --value <token>  Create an Anthropic secret. Errors if one
 *                             already exists unless --force is passed.
 *
 * The actual user-facing prompt (subscription vs API key, paste the token)
 * stays in the /new-setup SKILL.md. This step is just the machine side:
 * it calls `onecli secrets list` / `onecli secrets create` and emits a
 * structured status block. The token value is never logged.
 */
import { execFileSync } from 'child_process';
import os from 'os';
import path from 'path';

import { log } from '../src/log.js';
import { emitStatus } from './status.js';

const LOCAL_BIN = path.join(os.homedir(), '.local', 'bin');

interface Args {
  mode: 'check' | 'create';
  value?: string;
  force: boolean;
}

function childEnv(): NodeJS.ProcessEnv {
  const parts = [LOCAL_BIN];
  if (process.env.PATH) parts.push(process.env.PATH);
  return { ...process.env, PATH: parts.join(path.delimiter) };
}

function parseArgs(args: string[]): Args {
  let mode: 'check' | 'create' = 'check';
  let value: string | undefined;
  let force = false;

  for (let i = 0; i < args.length; i++) {
    const key = args[i];
    const val = args[i + 1];
    switch (key) {
      case '--check':
        mode = 'check';
        break;
      case '--create':
        mode = 'create';
        break;
      case '--value':
        value = val;
        i++;
        break;
      case '--force':
        force = true;
        break;
    }
  }

  if (mode === 'create' && !value) {
    emitStatus('AUTH', {
      STATUS: 'failed',
      ERROR: 'missing_value_for_create',
      LOG: 'logs/setup.log',
    });
    process.exit(2);
  }

  return { mode, value, force };
}

interface OnecliSecret {
  id: string;
  name: string;
  type: string;
  hostPattern: string | null;
}

function listSecrets(): OnecliSecret[] {
  const out = execFileSync('onecli', ['secrets', 'list'], {
    encoding: 'utf-8',
    env: childEnv(),
    stdio: ['ignore', 'pipe', 'ignore'],
  });
  const parsed = JSON.parse(out) as { data?: unknown };
  return Array.isArray(parsed.data) ? (parsed.data as OnecliSecret[]) : [];
}

function findAnthropicSecret(secrets: OnecliSecret[]): OnecliSecret | undefined {
  return secrets.find((s) => s.type === 'anthropic');
}

function createAnthropicSecret(value: string): void {
  // `value` is a credential — do not log it, do not echo, do not pass through a shell.
  execFileSync(
    'onecli',
    [
      'secrets',
      'create',
      '--name',
      'Anthropic',
      '--type',
      'anthropic',
      '--value',
      value,
      '--host-pattern',
      'api.anthropic.com',
    ],
    {
      env: childEnv(),
      stdio: ['ignore', 'ignore', 'pipe'],
    },
  );
}

export async function run(args: string[]): Promise<void> {
  const { mode, value, force } = parseArgs(args);

  let secrets: OnecliSecret[];
  try {
    secrets = listSecrets();
  } catch (err) {
    log.error('onecli secrets list failed', { err });
    emitStatus('AUTH', {
      STATUS: 'failed',
      ERROR: 'onecli_list_failed',
      HINT: 'Is OneCLI running? Run `/new-setup` from the onecli step.',
      LOG: 'logs/setup.log',
    });
    process.exit(1);
  }

  const existing = findAnthropicSecret(secrets);

  if (mode === 'check') {
    emitStatus('AUTH', {
      SECRET_PRESENT: !!existing,
      ANTHROPIC_OK: !!existing,
      STATUS: existing ? 'success' : 'missing',
      ...(existing ? { SECRET_NAME: existing.name, SECRET_ID: existing.id } : {}),
      LOG: 'logs/setup.log',
    });
    return;
  }

  // mode === 'create'
  if (existing && !force) {
    emitStatus('AUTH', {
      SECRET_PRESENT: true,
      STATUS: 'skipped',
      REASON: 'anthropic_secret_already_exists',
      SECRET_NAME: existing.name,
      SECRET_ID: existing.id,
      HINT: 'Re-run with --force to replace, or delete the existing secret first.',
      LOG: 'logs/setup.log',
    });
    return;
  }

  try {
    createAnthropicSecret(value!);
  } catch (err) {
    const e = err as { stderr?: string | Buffer; status?: number };
    const stderr = typeof e.stderr === 'string' ? e.stderr : e.stderr?.toString('utf-8') ?? '';
    log.error('onecli secrets create failed', { status: e.status, stderr });
    emitStatus('AUTH', {
      STATUS: 'failed',
      ERROR: 'onecli_create_failed',
      EXIT_CODE: e.status ?? -1,
      LOG: 'logs/setup.log',
    });
    process.exit(1);
  }

  // Re-verify
  const updated = findAnthropicSecret(listSecrets());

  emitStatus('AUTH', {
    SECRET_PRESENT: !!updated,
    ANTHROPIC_OK: !!updated,
    CREATED: true,
    STATUS: updated ? 'success' : 'failed',
    ...(updated ? { SECRET_NAME: updated.name, SECRET_ID: updated.id } : {}),
    LOG: 'logs/setup.log',
  });
}

/**
 * Step: signal-auth — link this host to an existing Signal account via
 * signal-cli's QR-code flow.
 *
 * signal-cli `link` opens a bi-directional handshake with the Signal
 * servers: it prints one line containing a linking URL (`sgnl://linkdevice?…`
 * or older `tsdevice://linkdevice?…`), then blocks until either the user
 * scans it from an existing Signal install, or the code expires. On
 * success, a secondary account is created under the user's signal-cli
 * data directory, associated with the phone number of the scanner.
 *
 * Methods:
 *   (no args)                    Spawn signal-cli link, emit SIGNAL_AUTH_QR
 *                                with the URL, wait for completion.
 *
 * Block schema (parent parses these):
 *   SIGNAL_AUTH_QR       { QR: "<sgnl:// or tsdevice:// url>" }   — one-shot
 *   SIGNAL_AUTH          { STATUS: success, ACCOUNT: +<digits> }  — terminal
 *                        { STATUS: skipped, ACCOUNT, REASON: already-authenticated }
 *                        { STATUS: failed, ERROR: <reason> }
 *
 * STATUS values match the runner's vocabulary (success/skipped/failed) so
 * spawnStep recognises them and sets `ok` correctly; Signal-specific UI
 * lives in setup/channels/signal.ts.
 *
 * If one or more accounts are already linked (discovered via
 * `signal-cli -o json listAccounts`), the step emits SIGNAL_AUTH
 * STATUS=skipped with the first account so the driver can reuse it.
 * Selecting a different existing account is a driver concern.
 */
import { spawn, spawnSync } from 'child_process';

import { emitStatus } from './status.js';

const LINK_TIMEOUT_MS = 180_000;
const DEFAULT_DEVICE_NAME = 'NanoClaw';

interface SignalAccount {
  account?: string;
  registered?: boolean;
}

function cliPath(): string {
  return process.env.SIGNAL_CLI_PATH || 'signal-cli';
}

/**
 * Query signal-cli for currently linked accounts. Empty array if none
 * configured, no binary, or the call fails for any other reason.
 */
function listAccounts(): string[] {
  const cli = cliPath();
  try {
    const res = spawnSync(cli, ['-o', 'json', 'listAccounts'], {
      encoding: 'utf-8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    if (res.status !== 0) return [];
    const parsed = JSON.parse(res.stdout || '[]') as SignalAccount[];
    return parsed
      .filter((a) => a.registered !== false)
      .map((a) => a.account ?? '')
      .filter(Boolean);
  } catch {
    return [];
  }
}

export async function run(_args: string[]): Promise<void> {
  const cli = cliPath();

  // Verify signal-cli exists before we commit to the long-running link.
  // The driver checks too, but this keeps the step honest when run alone.
  const probe = spawnSync(cli, ['--version'], {
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  if (probe.error || probe.status !== 0) {
    emitStatus('SIGNAL_AUTH', {
      STATUS: 'failed',
      ERROR: 'signal-cli not found. Install signal-cli first.',
    });
    return;
  }

  const existing = listAccounts();
  if (existing.length > 0) {
    emitStatus('SIGNAL_AUTH', {
      STATUS: 'skipped',
      ACCOUNT: existing[0],
      REASON: 'already-authenticated',
    });
    return;
  }

  await new Promise<void>((resolve) => {
    let settled = false;
    let qrEmitted = false;

    const finish = (block: Record<string, string | number | boolean>, code: number): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      emitStatus('SIGNAL_AUTH', block);
      resolve();
      setTimeout(() => process.exit(code), 500);
    };

    const timer = setTimeout(() => {
      try {
        child.kill('SIGTERM');
      } catch {
        /* ignore */
      }
      finish({ STATUS: 'failed', ERROR: 'qr_timeout' }, 1);
    }, LINK_TIMEOUT_MS);

    const child = spawn(cli, ['link', '--name', DEFAULT_DEVICE_NAME], {
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    // stdout carries the URL on the first line; subsequent lines may print
    // status like "Associated with: +1555…". We don't strictly need to parse
    // the number — listAccounts after exit is the source of truth — but the
    // URL match drives the QR emit, which is the whole point.
    let stdoutBuf = '';
    const handleStdout = (chunk: Buffer): void => {
      stdoutBuf += chunk.toString('utf-8');
      let idx: number;
      while ((idx = stdoutBuf.indexOf('\n')) !== -1) {
        const line = stdoutBuf.slice(0, idx).trim();
        stdoutBuf = stdoutBuf.slice(idx + 1);
        if (!line) continue;
        // Match both modern (sgnl://) and legacy (tsdevice://) schemes.
        if (/^(sgnl|tsdevice):\/\/linkdevice\?/.test(line) && !qrEmitted) {
          qrEmitted = true;
          emitStatus('SIGNAL_AUTH_QR', { QR: line });
        }
      }
    };
    child.stdout.on('data', handleStdout);

    // Capture stderr for the transcript / log — signal-cli writes warnings
    // and errors there. We don't emit on partial stderr lines since a
    // successful link can still produce noise.
    let stderrBuf = '';
    child.stderr.on('data', (chunk: Buffer) => {
      stderrBuf += chunk.toString('utf-8');
    });

    child.on('error', (err) => {
      finish({ STATUS: 'failed', ERROR: `spawn error: ${err.message}` }, 1);
    });

    child.on('close', (code) => {
      // After a successful link, signal-cli exits 0 and the newly linked
      // account shows up in listAccounts. Use that as the source of truth
      // rather than scraping stdout — more robust across signal-cli versions.
      if (code === 0) {
        const post = listAccounts();
        if (post.length === 0) {
          finish(
            { STATUS: 'failed', ERROR: 'link exited 0 but no account registered' },
            1,
          );
          return;
        }
        finish({ STATUS: 'success', ACCOUNT: post[0] }, 0);
        return;
      }

      // Non-zero exit. Surface the last non-empty stderr line for context;
      // signal-cli's own error messages are usually informative.
      const lastErr =
        stderrBuf
          .split('\n')
          .map((l) => l.trim())
          .filter(Boolean)
          .slice(-1)[0] ?? `signal-cli link exited with code ${code}`;
      finish({ STATUS: 'failed', ERROR: lastErr }, 1);
    });
  });
}

/**
 * Step: whatsapp-auth — standalone WhatsApp (Baileys) authentication.
 *
 * Forked from the channels-branch version so setup:auto's driver can render
 * the terminal UX itself (inside clack) instead of the step dumping a raw QR
 * to stdout. The browser method has been dropped — one less moving part and
 * it kept biting headless/SSH users.
 *
 * Methods:
 *   --method qr (default)          Emit each rotating QR as a status block
 *                                  with the raw QR string. Driver renders.
 *   --method pairing-code --phone  Request a pairing code. Emitted in a
 *                                  status block once the Baileys call returns.
 *
 * Block schema (parent parses these):
 *   WHATSAPP_AUTH_QR             { QR: "<raw>" }              — repeats
 *   WHATSAPP_AUTH_PAIRING_CODE   { CODE: "XXXX-XXXX" }        — one-shot
 *   WHATSAPP_AUTH                { STATUS: success }          — terminal
 *                                { STATUS: skipped, AUTH_DIR, REASON }
 *                                { STATUS: failed, ERROR: <reason> }
 *
 * STATUS values are kept in the runner's vocabulary (success/skipped/failed)
 * so `spawnStep` recognises them and sets `ok` correctly; WhatsApp-specific
 * UI text (e.g. "WhatsApp linked") lives in the driver's block handler.
 *
 * On success, credentials land in store/auth/ and the process exits 0.
 */
import fs from 'fs';
import path from 'path';
import { createRequire } from 'module';
// Named import (not default) — pino's d.ts under NodeNext resolves the
// default export to `typeof pino` (namespace), which isn't callable. The
// named `pino` export resolves to the callable function.
import { pino } from 'pino';

import {
  makeWASocket,
  Browsers,
  DisconnectReason,
  fetchLatestWaWebVersion,
  makeCacheableSignalKeyStore,
  useMultiFileAuthState,
} from '@whiskeysockets/baileys';
import { emitStatus } from './status.js';

const AUTH_DIR = path.join(process.cwd(), 'store', 'auth');
const PAIRING_CODE_FILE = path.join(process.cwd(), 'store', 'pairing-code.txt');
const baileysLogger = pino({ level: 'silent' });

// Baileys v6 bug: getPlatformId sends charCode (49) instead of enum value (1).
// Fixed in Baileys 7.x but not backported. Without this patch pairing codes
// fail with "couldn't link device" because WhatsApp receives an invalid
// platform id. createRequire because proto is not a named ESM export.
const _require = createRequire(import.meta.url);
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const { proto } = _require('@whiskeysockets/baileys') as { proto: any };
try {
  const _generics = _require(
    '@whiskeysockets/baileys/lib/Utils/generics',
  ) as Record<string, unknown>;
  _generics.getPlatformId = (browser: string): string => {
    const platformType =
      proto.DeviceProps.PlatformType[
        browser.toUpperCase() as keyof typeof proto.DeviceProps.PlatformType
      ];
    return platformType ? platformType.toString() : '1';
  };
} catch {
  // If CJS require fails, QR auth still works; only pairing code may be affected.
}

type AuthMethod = 'qr' | 'pairing-code';

function parseArgs(args: string[]): { method: AuthMethod; phone?: string } {
  let method: AuthMethod = 'qr';
  let phone: string | undefined;

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--method': {
        const raw = args[++i];
        if (raw === 'qr' || raw === 'pairing-code') {
          method = raw;
        } else {
          console.error(`Unknown --method: ${raw} (expected 'qr' or 'pairing-code')`);
          process.exit(1);
        }
        break;
      }
      case '--phone':
        phone = args[++i];
        break;
    }
  }

  if (method === 'pairing-code' && !phone) {
    console.error('--phone is required for pairing-code method');
    process.exit(1);
  }

  return { method, phone };
}

export async function run(args: string[]): Promise<void> {
  const { method, phone } = parseArgs(args);

  if (fs.existsSync(path.join(AUTH_DIR, 'creds.json'))) {
    emitStatus('WHATSAPP_AUTH', {
      STATUS: 'skipped',
      REASON: 'already-authenticated',
      AUTH_DIR,
    });
    return;
  }

  fs.mkdirSync(AUTH_DIR, { recursive: true });

  return new Promise<void>((resolve) => {
    const timeout = setTimeout(() => {
      emitStatus('WHATSAPP_AUTH', { STATUS: 'failed', ERROR: 'timeout' });
      process.exit(1);
    }, 120_000);

    let succeeded = false;
    function succeed(): void {
      if (succeeded) return;
      succeeded = true;
      clearTimeout(timeout);
      try {
        if (fs.existsSync(PAIRING_CODE_FILE)) fs.unlinkSync(PAIRING_CODE_FILE);
      } catch {
        // ignore — the pairing code file is best-effort cleanup
      }
      emitStatus('WHATSAPP_AUTH', { STATUS: 'success' });
      resolve();
      // Give a moment for creds to flush before exiting.
      setTimeout(() => process.exit(0), 1000);
    }

    async function connectSocket(isReconnect = false): Promise<void> {
      const { state, saveCreds } = await useMultiFileAuthState(AUTH_DIR);
      const { version } = await fetchLatestWaWebVersion({}).catch(() => ({
        version: undefined,
      }));

      const sock = makeWASocket({
        version,
        auth: {
          creds: state.creds,
          keys: makeCacheableSignalKeyStore(state.keys, baileysLogger),
        },
        printQRInTerminal: false,
        logger: baileysLogger,
        browser: Browsers.macOS('Chrome'),
      });

      // Request pairing code only on first connect (not reconnect after 515).
      if (
        !isReconnect &&
        method === 'pairing-code' &&
        phone &&
        !state.creds.registered
      ) {
        setTimeout(async () => {
          try {
            const code = await sock.requestPairingCode(phone);
            fs.writeFileSync(PAIRING_CODE_FILE, code, 'utf-8');
            emitStatus('WHATSAPP_AUTH_PAIRING_CODE', { CODE: code });
          } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            emitStatus('WHATSAPP_AUTH', { STATUS: 'failed', ERROR: message });
            process.exit(1);
          }
        }, 3000);
      }

      sock.ev.on('connection.update', (update) => {
        const { connection, lastDisconnect, qr } = update;

        // QR method: emit each rotation as a block. Parent renders.
        if (qr && method === 'qr') {
          emitStatus('WHATSAPP_AUTH_QR', { QR: qr });
        }

        if (connection === 'open') {
          succeed();
          sock.end(undefined);
        }

        if (connection === 'close') {
          const reason = (
            lastDisconnect?.error as { output?: { statusCode?: number } }
          )?.output?.statusCode;
          if (reason === DisconnectReason.loggedOut) {
            clearTimeout(timeout);
            emitStatus('WHATSAPP_AUTH', {
              STATUS: 'failed',
              ERROR: 'logged_out',
            });
            process.exit(1);
          } else if (reason === DisconnectReason.timedOut) {
            clearTimeout(timeout);
            emitStatus('WHATSAPP_AUTH', {
              STATUS: 'failed',
              ERROR: 'qr_timeout',
            });
            process.exit(1);
          } else if (reason === 515) {
            // 515 = stream error after pairing succeeds but before registration
            // completes. Reconnect to finish the handshake.
            connectSocket(true);
          }
        }
      });

      sock.ev.on('creds.update', saveCreds);
    }

    connectSocket();
  });
}

/**
 * migrate-v2 step: channel-auth
 *
 * Copy channel auth state from v1 to v2 for selected channels.
 * Handles both env keys and on-disk auth files (Baileys, Matrix, etc.)
 * per the CHANNEL_AUTH_REGISTRY.
 *
 * Usage: pnpm exec tsx setup/migrate-v2/channel-auth.ts <v1-path> <channel1> [channel2...]
 */
import fs from 'fs';
import path from 'path';

import { CHANNEL_AUTH_REGISTRY } from './shared.js';

function parseEnv(filePath: string): Map<string, string> {
  const out = new Map<string, string>();
  if (!fs.existsSync(filePath)) return out;
  for (const line of fs.readFileSync(filePath, 'utf-8').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq <= 0) continue;
    out.set(trimmed.slice(0, eq).trim(), trimmed.slice(eq + 1));
  }
  return out;
}

function appendEnvKey(envPath: string, key: string, value: string): boolean {
  const existing = parseEnv(envPath);
  if (existing.has(key)) return false;

  let content = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf-8') : '';
  if (content && !content.endsWith('\n')) content += '\n';
  content += `${key}=${value}\n`;
  fs.writeFileSync(envPath, content);
  return true;
}

function copyGlob(v1Root: string, v2Root: string, relativePath: string): string[] {
  const src = path.join(v1Root, relativePath);
  if (!fs.existsSync(src)) return [];

  const copied: string[] = [];
  const stat = fs.statSync(src);

  if (stat.isFile()) {
    const dst = path.join(v2Root, relativePath);
    if (!fs.existsSync(dst)) {
      fs.mkdirSync(path.dirname(dst), { recursive: true });
      fs.copyFileSync(src, dst);
      copied.push(relativePath);
    }
  } else if (stat.isDirectory()) {
    const dst = path.join(v2Root, relativePath);
    fs.mkdirSync(dst, { recursive: true });
    for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
      const sub = path.join(relativePath, entry.name);
      copied.push(...copyGlob(v1Root, v2Root, sub));
    }
  }

  return copied;
}

function main(): void {
  const args = process.argv.slice(2);
  const v1Path = args[0];
  const channels = args.slice(1);

  if (!v1Path || channels.length === 0) {
    console.error('Usage: tsx setup/migrate-v2/channel-auth.ts <v1-path> <channel1> [channel2...]');
    process.exit(1);
  }

  const v1EnvPath = path.join(v1Path, '.env');
  const v2EnvPath = path.join(process.cwd(), '.env');
  const v1Env = parseEnv(v1EnvPath);

  let envKeysCopied = 0;
  let filesCopied = 0;
  let channelsProcessed = 0;
  const missing: string[] = [];

  for (const channel of channels) {
    const spec = CHANNEL_AUTH_REGISTRY[channel];
    if (!spec) {
      // Unknown channel — just try copying env keys with common naming
      channelsProcessed++;
      continue;
    }

    // Copy env keys
    for (const key of spec.v1EnvKeys) {
      const value = v1Env.get(key);
      if (value) {
        if (appendEnvKey(v2EnvPath, key, value)) {
          envKeysCopied++;
        }
      }
    }

    // Check required v2 keys — report missing ones
    const v2Env = parseEnv(v2EnvPath);
    for (const req of spec.requiredV2Keys) {
      if (!v2Env.has(req.key)) {
        missing.push(`${channel}:${req.key} (${req.where})`);
      }
    }

    // Copy on-disk auth files
    for (const candidate of spec.candidatePaths) {
      const copied = copyGlob(v1Path, process.cwd(), candidate);
      filesCopied += copied.length;
    }

    channelsProcessed++;
  }

  // Sync to data/env/env
  if (fs.existsSync(v2EnvPath)) {
    const containerEnvDir = path.join(process.cwd(), 'data', 'env');
    try {
      fs.mkdirSync(containerEnvDir, { recursive: true });
      fs.copyFileSync(v2EnvPath, path.join(containerEnvDir, 'env'));
    } catch { /* non-fatal */ }
  }

  console.log(`OK:channels=${channelsProcessed},env_keys=${envKeysCopied},files=${filesCopied}`);
  if (missing.length > 0) {
    console.log(`MISSING:${missing.join(',')}`);
  }
}

main();

{
  "name": "nanoclaw-agent-runner",
  "version": "1.0.0",
  "type": "module",
  "description": "Container-side agent runner for NanoClaw",
  "scripts": {
    "start": "bun src/index.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
