/**
 * Step: cli-agent — Create the scratch CLI agent for `/new-setup`.
 *
 * Thin wrapper around `scripts/init-cli-agent.ts`. Emits a status block so
 * /new-setup SKILL.md can parse the result without having to read the
 * script's plain stdout.
 *
 * Args:
 *   --display-name <name>   (required) operator's display name
 *   --agent-name   <name>   (optional) agent persona name, defaults to display-name
 *   --folder       <name>   (optional) explicit folder name, defaults to cli-with-<normalized-display-name>
 */
import { execFileSync } from 'child_process';
import path from 'path';

import { log } from '../src/log.js';
import { emitStatus } from './status.js';

function parseArgs(args: string[]): {
  displayName: string;
  agentName?: string;
  folder?: string;
} {
  let displayName: string | undefined;
  let agentName: string | undefined;
  let folder: string | undefined;

  for (let i = 0; i < args.length; i++) {
    const key = args[i];
    const val = args[i + 1];
    switch (key) {
      case '--display-name':
        displayName = val;
        i++;
        break;
      case '--agent-name':
        agentName = val;
        i++;
        break;
      case '--folder':
        folder = val;
        i++;
        break;
    }
  }

  if (!displayName) {
    emitStatus('CLI_AGENT', {
      STATUS: 'failed',
      ERROR: 'missing_display_name',
      LOG: 'logs/setup.log',
    });
    process.exit(2);
  }

  return { displayName, agentName, folder };
}

export async function run(args: string[]): Promise<void> {
  const { displayName, agentName, folder } = parseArgs(args);

  const projectRoot = process.cwd();
  const script = path.join(projectRoot, 'scripts', 'init-cli-agent.ts');

  const scriptArgs = ['exec', 'tsx', script, '--display-name', displayName];
  if (agentName) scriptArgs.push('--agent-name', agentName);
  if (folder) scriptArgs.push('--folder', folder);

  log.info('Invoking init-cli-agent', { displayName, agentName });

  try {
    execFileSync('pnpm', scriptArgs, {
      cwd: projectRoot,
      stdio: ['ignore', 'pipe', 'pipe'],
      encoding: 'utf-8',
    });
  } catch (err) {
    const e = err as { stdout?: string; stderr?: string; status?: number };
    log.error('init-cli-agent failed', {
      status: e.status,
      stdout: e.stdout,
      stderr: e.stderr,
    });
    emitStatus('CLI_AGENT', {
      STATUS: 'failed',
      ERROR: 'init_script_failed',
      EXIT_CODE: e.status ?? -1,
      LOG: 'logs/setup.log',
    });
    process.exit(1);
  }

  emitStatus('CLI_AGENT', {
    DISPLAY_NAME: displayName,
    AGENT_NAME: agentName || displayName,
    CHANNEL: 'cli/local',
    STATUS: 'success',
    LOG: 'logs/setup.log',
  });
}

/**
 * Browser-open helpers shared across channel setup flows.
 *
 * `openUrl` is best-effort — silent on failure, so headless/SSH/WSL
 * environments where `open`/`xdg-open` isn't wired up don't crash the
 * setup. The URL should always be visible in the clack note that calls
 * this so the user can copy-paste if the auto-open doesn't land.
 *
 * `confirmThenOpen` pauses for the operator before triggering the open —
 * the browser tends to steal focus when it pops, and a split-second
 * "wait what just happened" moment is worse than letting the user hit
 * Enter when they're ready. On headless devices (no graphical session
 * available) it skips both the prompt and the open: there's no browser
 * to launch, the surrounding `note(...)` already shows the URL for
 * copy-paste on another device, and the next prompt in the channel
 * flow ("Got your bot token?" etc.) provides the natural completion
 * confirmation.
 */
import { spawn } from 'child_process';

import * as p from '@clack/prompts';
import k from 'kleur';

import { isHeadless } from '../platform.js';
import { ensureAnswer } from './runner.js';

/** Best-effort open of a URL in the user's default browser. Silent on failure. */
export function openUrl(url: string): void {
  try {
    const cmd = process.platform === 'darwin' ? 'open' : 'xdg-open';
    const child = spawn(cmd, [url], { stdio: 'ignore', detached: true });
    child.on('error', () => {
      // Headless / no browser / unknown command — URL is printed in the
      // calling note so the user can copy-paste.
    });
    child.unref();
  } catch {
    // swallow — URL is visible in the note.
  }
}

/**
 * Format a URL for inclusion in a setup `note(...)` card. On
 * headless devices we surface the URL inside the card with a
 * "Get started:" label at full strength — copy-pasting onto
 * another device is the actual action, not an incidental
 * reference. The leading `\n` acts as a visual separator from
 * the body steps above; callers `.filter(line => line !== null)`
 * before joining, so on GUI we drop the line entirely (and the
 * URL ends up below the next-step confirm prompt as a "if
 * browser does not appear, please visit" fallback — see
 * `confirmThenOpen`).
 */
export function formatNoteLink(url: string): string | null {
  if (isHeadless()) return `\nGet started: ${url}`;
  return null;
}

/**
 * Gate a browser-open on a confirm so the user is ready for their browser
 * to take focus. Proceeds on cancel as well. On headless devices both the
 * prompt and the open are skipped — the URL is already surfaced inside
 * the surrounding note (via `formatNoteLink`).
 *
 * On GUI devices the confirm message includes the fallback URL on the
 * lines below the action ("If browser does not appear, please visit:
 * <url>" in dim) so the user has a copy-paste path right next to the
 * action button without needing to scroll back up to the card.
 */
export async function confirmThenOpen(
  url: string,
  message = 'Press Enter to open your browser',
): Promise<void> {
  if (isHeadless()) return;
  const fallback = `\n${k.dim(`If browser does not appear, please visit: ${url}`)}`;
  ensureAnswer(
    await p.confirm({
      message: `${message}${fallback}`,
      initialValue: true,
    }),
  );
  openUrl(url);
}

/**
 * Round-trip check against the CLI Unix socket.
 *
 * Shared by `setup/verify.ts` (end-of-run health check) and `setup/auto.ts`
 * (confirm the freshly-wired agent actually responds before prompting the
 * user to chat with it).
 *
 * Exit-code contract follows `scripts/chat.ts`:
 *   0  → got a reply on stdout
 *   2  → socket unreachable (service not running or wrong checkout)
 *   3  → no reply before chat.ts's own 120s hard stop
 * This wrapper also guards with its own timeout in case chat.ts hangs.
 */
import { spawn } from 'child_process';

export type PingResult = 'ok' | 'no_reply' | 'socket_error' | 'auth_error';

export function classifyPingResult(exitCode: number | null, stdout: string, stderr = ''): PingResult {
  const output = `${stdout}\n${stderr}`;
  if (
    /Invalid bearer token/i.test(output) ||
    /authentication[_ ]error/i.test(output) ||
    /Failed to authenticate/i.test(output) ||
    /Please run \/login/i.test(output) ||
    /Not logged in/i.test(output) ||
    /Invalid API key/i.test(output)
  ) {
    return 'auth_error';
  }
  if (exitCode === 2) return 'socket_error';
  if (exitCode === 0 && stdout.trim().length > 0) return 'ok';
  return 'no_reply';
}

export function pingCliAgent(timeoutMs = 30_000): Promise<PingResult> {
  return new Promise((resolve) => {
    const child = spawn('pnpm', ['run', 'chat', 'ping'], {
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill('SIGKILL');
      resolve('no_reply');
    }, timeoutMs);

    child.stdout.on('data', (chunk: Buffer) => {
      stdout += chunk.toString('utf-8');
    });
    child.stderr.on('data', (chunk: Buffer) => {
      stderr += chunk.toString('utf-8');
    });
    child.on('close', (code) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(classifyPingResult(code, stdout, stderr));
    });
    child.on('error', () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve('socket_error');
    });
  });
}

import type { AgentGroupMember } from '../../../types.js';
import { getDb } from '../../../db/connection.js';
import { isAdminOfAgentGroup, isGlobalAdmin, isOwner } from './user-roles.js';

export function addMember(row: AgentGroupMember): void {
  getDb()
    .prepare(
      `INSERT OR IGNORE INTO agent_group_members (user_id, agent_group_id, added_by, added_at)
       VALUES (@user_id, @agent_group_id, @added_by, @added_at)`,
    )
    .run(row);
}

export function removeMember(userId: string, agentGroupId: string): void {
  getDb().prepare('DELETE FROM agent_group_members WHERE user_id = ? AND agent_group_id = ?').run(userId, agentGroupId);
}

export function getMembers(agentGroupId: string): AgentGroupMember[] {
  return getDb()
    .prepare('SELECT * FROM agent_group_members WHERE agent_group_id = ? ORDER BY added_at')
    .all(agentGroupId) as AgentGroupMember[];
}

/**
 * Is the user "known" in this agent group?
 * Owner, global admin, and scoped admin are implicitly members.
 */
export function isMember(userId: string, agentGroupId: string): boolean {
  if (isOwner(userId) || isGlobalAdmin(userId) || isAdminOfAgentGroup(userId, agentGroupId)) {
    return true;
  }
  const row = getDb()
    .prepare('SELECT 1 FROM agent_group_members WHERE user_id = ? AND agent_group_id = ? LIMIT 1')
    .get(userId, agentGroupId);
  return !!row;
}

/** Direct row lookup — does not honor the admin/owner implicit-membership rule. */
export function hasMembershipRow(userId: string, agentGroupId: string): boolean {
  const row = getDb()
    .prepare('SELECT 1 FROM agent_group_members WHERE user_id = ? AND agent_group_id = ? LIMIT 1')
    .get(userId, agentGroupId);
  return !!row;
}

